export const looseKey=text=>String(text).replace(/[’‘]/g,"'").replace(/^[^A-Za-z0-9#“"']+|[^A-Za-z0-9#.!?”"')]+$/g,'').replace(/\s+/g,' ').trim().toLowerCase();
