// Labels joined with · or a colon are translated part by part (level codes and numbers stay).
function supportParts(text){
 const sep=text.includes(' · ')?' · ':/^[^:]{2,40}: \S/.test(text)?': ':null;if(!sep)return null;
 const parts=text.split(sep).map(p=>p.trim());if(parts.length<2)return null;
 const out=parts.map(p=>{
  if(!/[A-Za-z]{2,}/.test(p)||levelCode.test(p))return {ps:p,rps:p,ur:p,rur:p};
  const coded=/^(.+) ((?:Pre-)?[ABC][12]\+?)$/.exec(p),label=coded&&support(coded[1]);
  return label?{ps:`${label.ps} ${coded[2]}`,rps:`${label.rps} ${coded[2]}`,ur:`${label.ur} ${coded[2]}`,rur:`${label.rur} ${coded[2]}`}:support(p);
 });
 if(out.some(x=>!x))return null;
 const join=k=>out.map(x=>x[k]).join(sep);return all4(join('ps'),join('rps'),join('ur'),join('rur'),text);
}
