 if(numbers){const item=numbered.get(key.replace(/\d+/g,'#'));if(item)return fillNumbers(item,numbers,text);}
 for(const [re,make] of screenPatterns){const m=re.exec(text.trim());if(m){const made=make(text,...m.slice(1));if(made)return made;}}
