 if(build){const target=build[1]||build[2];return {en:text,ps:`دا جوړ کړه: ${target}`,rps:`Da jor kra: ${target}`,ur:`یہ بنائیں: ${target}`,rur:`Yeh banayein: ${target}`};}
 const find=/^Find (.+)\.$/.exec(text);
 if(find){const w=wordFor(find[1]);if(w)return {en:text,ps:`${w.ps} پیدا کړه.`,rps:`${w.rps} paida kra.`,ur:`${w.ur} ڈھونڈیں۔`,rur:`${w.rur} dhoondein.`};}
