 if(w){const emoji=text.match(/^[^A-Za-z]*/)[0].trim(),pre=emoji?emoji+' ':'';return {en:text,ps:pre+w.ps,rps:pre+w.rps,ur:pre+w.ur,rur:pre+w.rur};}
